TLM.f("Sancti/02-10",{"officium":"S. Scholasticæ Virginis","rule":["vide C6b;","Gloria"],"ruleInherited":["Prefatio=Virginis"],"fallback":"Commune/C6b","from":{"Introitus":"Commune/C6b","Lectio":"Commune/C6b","Graduale":"Commune/C6b","GradualeP":"Commune/C6b","Tractus":"Commune/C6b","Evangelium":"Commune/C6b","Offertorium":"Commune/C6b","Communio":"Commune/C6b"},"sections":{"Introitus":[{"k":"ref","la":"Ps 44:8"},{"k":"text","la":"Dilexísti justítiam, et odísti iniquitátem: proptérea unxit te Deus, Deus tuus, óleo lætítiæ præ consórtibus tuis. (Allelúja, allelúja.)"},{"k":"ref","la":"Ps 44:2"},{"k":"text","la":"Eructávit cor meum verbum bonum: dico ego ópera mea Regi."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Dilexísti justítiam, et odísti iniquitátem: proptérea unxit te Deus, Deus tuus, óleo lætítiæ præ consórtibus tuis. (Allelúja, allelúja.)"}],"Oratio":[{"k":"text","la":"Deus, qui ánimam beátæ Vírginis tuæ Scholásticæ ad ostendéndam innocéntiæ viam in colúmbæ spécie cœlum penetráre fecísti: da nobis ejus méritis et précibus ita innocénter vívere; ut ad ætérna mereámur gáudia perveníre."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Corínthios"},{"k":"ref","la":"2 Cor 10:17-18; 11:1-2"},{"k":"text","la":"Fratres: Qui gloriátur, in Dómino gloriétur. Non enim, qui seípsum comméndat, ille probátus est; sed quem Deus comméndat. Utinam sustinerétis módicum quid insipiéntiæ meæ, sed et supportáte me: æmulor enim vos Dei æmulatióne. Despóndi enim vos uni viro vírginem castam exhibére Christo."}],"Graduale":[{"k":"ref","la":"Ps 44:5"},{"k":"text","la":"Spécie tua et pulchritúdine tua inténde, próspere procéde et regna."},{"k":"text","la":"Propter veritátem et mansuetúdinem et justítiam: et dedúcet te mirabíliter déxtera tua.","mark":"V"},{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 44:15-16"},{"k":"text","la":"Adducéntur Regi Vírgines post eam: próximæ ejus afferéntur tibi in lætítia. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 44:15; 44:16"},{"k":"text","la":"Adducéntur Regi Vírgines post eam: próximæ ejus afferéntur tibi in lætítia. Allelúja."},{"k":"ref","la":"Ps 44:5"},{"k":"text","la":"Spécie tua et pulchritúdine tua inténde, próspere procéde et regna. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 44:5"},{"k":"text","la":"Spécie tua et pulchritúdine tua inténde, próspere procéde et regna."},{"k":"text","la":"Propter veritátem et mansuetúdinem et justítiam: et dedúcet te mirabíliter déxtera tua.","mark":"V"},{"k":"ref","la":"Ps 44:15-16"},{"k":"text","la":"Audi, fília, et vide, et inclína aurem tuam: quia concupívit Rex spéciem tuam."},{"k":"ref","la":"Ps 44:13; 44:10"},{"k":"text","la":"Vultum tuum deprecabúntur omnes dívites plebis: fíliæ regum in honóre tuo."},{"k":"ref","la":"Ps 44:15-16"},{"k":"text","la":"Adducéntur Regi Vírgines post eam: próximæ ejus afferéntur tibi."},{"k":"text","la":"Afferéntur in lætítia et exsultatióne: adducéntur in templum Regis.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 25:1-13"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis parábolam hanc: Símile erit regnum coelórum decem virgínibus: quæ, accipiéntes lámpades suas, exiérunt óbviam sponso et sponsæ. Quinque autem ex eis erant fátuæ, et quinque prudéntes: sed quinque fátuæ, accéptis lampádibus, non sumpsérunt óleum secum: prudéntes vero accepérunt óleum in vasis suis cum lampádibus. Moram autem faciénte sponso, dormitavérunt omnes et dormiérunt. Média autem nocte clamor factus est: Ecce, sponsus venit, exíte óbviam ei. Tunc surrexérunt omnes vírgines illae, et ornavérunt lámpades suas. Fátuæ autem sapiéntibus dixérunt: Date nobis de óleo vestro: quia lámpades nostræ exstinguúntur. Respondérunt prudéntes, dicéntes: Ne forte non suffíciat nobis et vobis, ite pótius ad vendéntes, et émite vobis. Dum autem irent émere, venit sponsus: et quæ parátæ erant, intravérunt cum eo ad núptias, et clausa est jánua. Novíssime vero véniunt et réliquæ vírgines, dicéntes: Dómine, Dómine, áperi nobis. At ille respóndens, ait: Amen, dico vobis, néscio vos. Vigiláte ítaque, quia nescítis diem neque horam."}],"Offertorium":[{"k":"ref","la":"Ps 44:10"},{"k":"text","la":"Fíliæ regum in honóre tuo, ástitit regína a dextris tuis in vestítu deauráto, circúmdata varietáte. (Allelúja.)"}],"Secreta":[{"k":"text","la":"Accépta tibi sit, Dómine, sacrátæ plebis oblátio pro tuórum honóre Sanctórum: quorum se méritis de tribulatióne percepísse cognóscit auxílium."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Matt 25:4-6"},{"k":"text","la":"Quinque prudéntes vírgines accepérunt óleum in vasis suis cum lampádibus: média autem nocte clamor factus est: Ecce, sponsus venit: exíte óbviam Christo Dómino. (Allelúja.)"}],"Postcommunio":[{"k":"text","la":"Satiásti, Dómine, famíliam tuam munéribus sacris: ejus, quǽsumus, semper interventióne nos réfove, cujus sollémnia celebrámus."},{"k":"macro","name":"Per Dominum"}]},"hr":{"5f74a5115cb0ce83":{"t":"Ps 44, 8, Ps 44, 2\n(Ps 44, 8) Ljubiš pravdu a mrziš nepravdu. Zato te je pomazao Bog, Bog tvoj, uljem radosti više nego drugarice tvoje. (Ps 44, 2) Iz srca mi navire radosna riječ, pripovijedam djela svoja Kralju.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 44, 8) Ljubiš pravdu a mrziš nepravdu. Zato te je pomazao Bog, Bog tvoj, uljem radosti više nego drugarice tvoje.","kn":"(Ps. 44, 8). Ti ljubiš pravdu i mrziš nepravdu, zato te pomazao Gospodin Bog tvoj uljem radosti izabravši te od svih dru.garica tvojih, Aleluja, Aleluja (Ps. 44, 2). Iz mog srca Izvire divna pjesma: djela su moja namijenjena kralju! Slava Ocu. Ti ljubiš.","knRef":"Kniewald 1942, str. 824–825 (snimka 413) (OCR)"},"d609c0327beb609d":{"t":"<i>Pomolimo se</i>.\nBože, koji si dao da se duša blažene djevice tvoje Skolastike vine u liku golubice u nebo, da tako očituješ nevinost njena života, daj nam po njezinim zaslugama i molitvama tako nevino živjeti da zavrijedimo doći do vječnih radosti.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji si duši svoje djevice Skoiastike dao da se vine u nebo u obliku golubice, da tako pokažeš nevinost njezina života, podaj, da i njezinim zagovorom i prošnjama, tako nevino živimo', te zaslužimo doći u vječne radosti, po G. n.","knRef":"Kniewald 1942, str. 506–507 (snimka 254) (OCR)"},"2e242204d5c46dd6":{"t":"2 Kor 10, 17-18, 11, 1-2\nČitanje Poslanice bl. Pavla apostola Korinćanima. Braćo, tko se hvali neka se hvali u Gospodinu. Jer nije prokušan onaj koji se sam hvali, nego koga Bog hvali. O da biste malo podnosili moje bezumlje! Ali ipak podnesite me, jer revnujem za vas Božjom revnošću. Zaručio sam vas jednom čovjeku Kristu da vas preda nj izvedem kao čistu djevicu.","kn":"Čitanje poslanice bi. Pavla apostola Korinćanima (II, 10, 17-18. 11, 1-2). Braćo! Koji se hvali, neka se hvali u Gospodinu. Jer nije prokušan onaj, koji se sam preporučuje, nego koga preporučuje Bog. O da biste ipodnesld nešto malo moje ludosti! Ali ipak r po'dnesite me, jer revnujem za vas Božjim žarom. Zaručio sam vas jednomu mužu, da vas privedem Kristu kao čistu djevicu.","knRef":"Kniewald 1942, str. 824–825 (snimka 413) (OCR)"},"7a556f19128f4056":{"t":"Ps 44, 5\nU svojoj veličanstvenoj ljepoti sretno pođi, napreduj i kraljuj. Zbog vjernosti, blagosti i pravednosti divno će te voditi tvoja desnica.\n\nPs 44, 11 i 12, Ps 44, 13 i 10, Ps 44, 15-16\nČuj, kćeri, i pogledaj i prikloni svoje uho, jer je Kralj zavolio tvoju ljepotu. Za pogledom tvojeg lica vapit će svi velikani, kraljevske će ti kćeri biti u pratnji. Za njom će poći pred Kralja djevice, drugarice će njezine poći k tebi. Poći će u radosti i veselju, poći će u hram Kraljev.","v":"ista misa na staroj stranici, latinski tekst odstupa (sličnost 0.98)","kn":"(Ps. 44, 5). U svojoj veličanstvenoj ljepoti sretno pođi, pohitaj prama pobjedi i kraljuj! Za istinu, pravdu i blagost se bori i neka te divno vodi desnica tvoja.\nZavlaka. (Ps. 44, 11, 12.) O djevice, vidi i čuj: zaboravi svoj narod i oca svoga dom. Za ljepotom tvojom teži kralj, tvoj Gospodin, ti ćeš mu podati čast (Ps. 44, 13, 10.) Najmoćniji ove zemlje slavit će tebe, pratit će te kćeri kraljevske (Ps. 44, 15, 16.) Prate je djevice i vode je kralju u radosti i veselju, vode je u hram Kraljev.","knRef":"Kniewald 1942, str. 826"},"04a5e5f3be261c56":{"t":"Mt 25, 1-13\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme reče Isus svojim učenicima: Kraljevstvo je nebesko kao deset djevica, koje uzeše svoje svjetiljke i iziđoše u susret zaručniku i zaručnici. Pet ih je bilo ludih, a pet mudrih. Pet ludih uzeše svjetiljke, a ne uzeše sa sobom ulja, a mudre sa svjetiljkama uzeše ulja u svojim posudama. Ali jer se zaručnik zabavio, sve zadrijemaše i zaspaše. A o ponoći nasta vika: Evo, ide zaručnik, iziđite mu u susret! Tada ustaše sve djevice i zapališe svoje svjetiljke. Lude tada reknu mudrima: Dajte nam od svoga ulja, jer se gase naše svjetiljke. Mudre odgovore: Da ne bi ponestalo nama i vama, idite radije do prodavača i kupite. Dok su išle kupovati, dođe zaručnik, i koje su bile spremne, uđu s njim na svadbu i zatvore se vrata. Napokon dođu i ostale djevice i reknu: Gospodine, Gospodine, otvori nam! On im odgovori: Zaista vam kažem: Ne poznam vas. Bdijte dakle, jer ne znate ni dana ni časa.","kn":"t Slijedi sv. evanđelje po Mateju (25, 1-13). U ono vrijeme reče Isus svojim učenicima ovu prispodobu: Kraljevstvo je nebesko kao deset djevica, koje uzeše svoje svjetiljke 1 iziđoše ususret zaručniku i zaručnici. Pet ih je bilo ludih, a pet mudrih. Pet ludih uzeše svjetiljke, a ne uzeše sa sobom ulja, a mudre sa svjetiljkama uzeše ulja u svojim posudama. Ali jer se zaručnik zabavio, sve zadrijemaše i zaspaše. A o ponoći nasta vika; Evo, ide zaručnik, iziđite mu ususret! Tada ustadoše sve djevice i zapališe svoje svjetUjke. Lude tada reknu mudrima: Dajte nam od svoga ulja, jer se gase naše svjetiljke. Mudre odgovore: Da ne bi ponestalo nama i vama, idite radije do prodavača i kupite. Dok su išle kupovati, dođe zaručnik, i koje'su bile spremne, uniđu s njim na svadbu i zatvore se vrata. Napokon dođu i ostale djevice i reknu: Gospodine, Gospodine, otvori nam! On im odgovori: Zaista vam kažem: Ne poznam vas. Bdijte, dakle, jer ne znate ni dana ni časa!","knRef":"Kniewald 1942, str. 826–827 (snimka 414) (OCR)"},"3ef3e3394cd6d09a":{"t":"Ps 44, 10\nKraljevske kćeri dolaze ti ususret, Kraljica stoji uz desnu tvoju ogrnuta presjajnom zlatnom haljinom.","kn":"(Ps. 44, 16). Pratit će te kćeri kraljevske: z desne tvoje sama kraljica, ogrnuta presjajnom zlatnom haljinom.","knRef":"Kniewald 1942, str. 826–827 (snimka 414) (OCR)"},"135c5bf58bce477d":{"t":"Neka ti bude, Gospodine, drag ovaj prinos što ga tvoj sveti narod prikazuje, u čast tvojih svetih priznavajući da je po njihovim zaslugama primio pomoć u nevolji.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","c":"T01"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Predslovlje. Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti, Oče svemogući, vjećni Bože, po Kristu, Gospodinu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i . blaženi Serafini zadružnim klicanjem zajedno slave. Zapovjedi, molimo, da se i naši glasovi združe s njihovima, smjernim ispovijedanjem govoreći:","knRef":"Kniewald 1942, str. 758–759 (snimka 380) (OCR)"},"a487c4b958415356":{"t":"Mt 25, 4 i 6\nPet je mudrih djevica uzelo ulje u svojim posudama zajedno sa svjetiljkama. A o ponoći začu se vika: Evo dolazi zaručnik, iziđite ususret Kristu Gospodinu.","kn":"(Mt. 25, 4, 6.) Pet je mudrih djevica uzelo ulje u posudama svojim sa svjetiljkama; a o ponoći nasta vika: Evo ide zaručnik, iziđite ususrte Kristu Gospodinu!","knRef":"Kniewald 1942, str. 826–827 (snimka 414) (OCR)"},"dfce8e9a1c23b4e0":{"t":"<i>Pomolimo se</i>.\nNasitio si, Gospodine, svoju obitelj svetim darovima, molimo da nas uvijek krijepiš na zagovor one čiju svečanost slavimo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo Te, Gospodine, pošto si nahranio svoju obitelj presvetim darovima, da nas uvijek krijepiš zagovorom one, koje blagdan slavimo, Po G. n.","knRef":"Kniewald 1942, str. 506–507 (snimka 254) (OCR)"},"c025d479900eacd4":{"t":"Ps 44, 5\nU svojoj veličanstvenoj ljepoti sretno pođi, napreduj i kraljuj. Zbog vjernosti, blagosti i pravednosti divno će te voditi tvoja desnica.\n\nPs 44, 15-16\n<i>Aleluja</i>, <i>aleluja</i>.\nZa njom će poći pred Kralja djevice, drugarice će njezine poći k tebi u radosti. <i>Aleluja</i>.","kn":"(Ps. 44, 5). U veličanstvenoj ljepoti svojoj sretno pođi, pohitaj prama pobjedi i kraljuj! Poradi istine i blagosti i pravde vodit će te divno desnica tvoja.\n\nAleluja-, Aleluja (Pr. 44, 15, 16). Prate je djevice I i vode je kralju u radosti i veselju. Aleluja (Ps. 44, , <i>aleluja</i>.","knRef":"Kniewald 1942, str. 832–833 (snimka 417) (OCR)"}},"variants":{"paschal":{"Graduale":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 44:15; 44:16"},{"k":"text","la":"Adducéntur Regi Vírgines post eam: próximæ ejus afferéntur tibi in lætítia. Allelúja."},{"k":"ref","la":"Ps 44:5"},{"k":"text","la":"Spécie tua et pulchritúdine tua inténde, próspere procéde et regna. Allelúja."}]}}});
